export interface ConnectorConfig {
  /** Calendly personal access token for fetching invitee details (if not in webhook payload). */
  calendlyToken: string
  /** Slack bot token with chat:write scope. */
  slackBotToken: string
  /** Slack channel ID (e.g., C01JASD6802) or name (e.g., #general). */
  slackChannel: string
  /** Injected fetch implementation for testing. */
  fetch?: typeof fetch
}

export interface CalendlyWebhookPayload {
  resource: {
    uri: string
  }
  invitee?: {
    name: string
    email: string
  }
  answers?: Array<{
    question: string
    answer: string
  }>
}

export interface InviteeDetails {
  name: string
  email: string
  answers?: Array<{
    question: string
    answer: string
  }>
}

export interface HandleResult {
  slackMessageTs: string
  slackChannel: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: CalendlyWebhookPayload): void {
  if (!payload.resource?.uri) {
    throw new Error('Missing required field: resource.uri')
  }
}

async function fetchInviteeDetails(
  uri: string,
  calendlyToken: string,
  fetchFn: typeof fetch,
): Promise<InviteeDetails> {
  const response = await fetchFn(uri, {
    method: 'GET',
    headers: {
      Authorization: `Bearer ${calendlyToken}`,
      Accept: 'application/json',
    },
  })

  if (!response.ok) {
    throw new Error(`Calendly GET ${uri} failed with status ${response.status}`)
  }

  const data = (await response.json()) as {
    invitee?: { name: string; email: string }
    answers?: Array<{ question: string; answer: string }>
  }

  if (!data.invitee?.name || !data.invitee?.email) {
    throw new Error('Invitee details response missing name or email')
  }

  return {
    name: data.invitee.name,
    email: data.invitee.email,
    answers: data.answers,
  }
}

function formatSlackText(invitee: InviteeDetails): string {
  const lines = [
    'New Calendly meeting booked!',
    `Name: ${invitee.name}`,
    `Email: ${invitee.email}`,
  ]

  if (invitee.answers && invitee.answers.length > 0) {
    const answersText = invitee.answers
      .map((a) => `${a.question} -> ${a.answer}`)
      .join('; ')
    lines.push(`Answers: ${answersText}`)
  }

  return lines.join('\n')
}

async function postToSlack(
  channel: string,
  text: string,
  slackBotToken: string,
  fetchFn: typeof fetch,
): Promise<string> {
  const response = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ channel, text }),
  })

  if (!response.ok) {
    throw new Error(`Slack chat.postMessage failed with status ${response.status}`)
  }

  const data = (await response.json()) as { ok: boolean; ts: string; channel: string }
  return data.ts
}

export async function handle(
  payload: CalendlyWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  validatePayload(payload)

  const fetchFn = getFetch(config)

  let invitee: InviteeDetails

  if (payload.invitee?.name && payload.invitee?.email) {
    invitee = {
      name: payload.invitee.name,
      email: payload.invitee.email,
      answers: payload.answers,
    }
  } else {
    invitee = await fetchInviteeDetails(payload.resource.uri, config.calendlyToken, fetchFn)
  }

  const text = formatSlackText(invitee)
  const slackMessageTs = await postToSlack(config.slackChannel, text, config.slackBotToken, fetchFn)

  return {
    slackMessageTs,
    slackChannel: config.slackChannel,
  }
}

